			            // 재조회용 dmDtlParam에 정보 저장
			            app.lookup("dmSearch").setValue("ERYY_GR_DSCSN_NO", vsEryyGrDscsnNo);
			            
			            // 데이터셋 클리어
			            app.lookup("dmDetail").reset();     // 상세정보
			            app.lookup("dmPrfmnc").reset();     // 지원서비스실적
			            app.lookup("dmUneartActbtCl").reset();
			            app.lookup("dsUnite").revert();     // 연합거리상담조회
