			/*
			 * 서치 인풋에서 click 이벤트 발생 시 호출.
			 * 사용자가 컨트롤을 클릭할 때 발생하는 이벤트.
			 */
			function onSipb_TRPR_NMClick(e){
			    var sipb_TRPR_NM = e.control;

			    var detailUrl   = "app/itgcm/bizcmmns/popup/trprInfoInqPop";
			    var detailTitle = "대상자정보 조회";
			    
			    var dsActn = app.lookup("dsActn");    
			    var nIdx     = util.Grid.getIndex(app, "grdActn");
			    var rowState = util.DataSet.getRowStateString(app, "dsActn", nIdx);    
			    
			    
			    if(rowState == 'I'){
			        
			        util.Dialog.open(app, detailUrl, detailTitle, 1380, 600, function(e) {
			    
			            var dialog = e.control;
			            var voReturnVal = dialog.returnValue;
			    
			            if(!ValueUtil.isNull(voReturnVal)){
			                for(var i=0; i<dsActn.getRowCount(); i++) {
			                    var sTrprInfoNo    = dsActn.getValue(i, "TRPR_INFO_NO");
			                    if(sTrprInfoNo == voReturnVal["TRPR_INFO_NO"]){
			                        util.Msg.alert(app, "해당 대상자가 존재합니다.\n다시 선택해주십시요.");
			                        return;
			                    }
			                 }   
			                    
			                dsActn.setValue( nIdx ,"TRPR_INFO_NO",  voReturnVal["TRPR_INFO_NO"]);     // 대상자번호
			                dsActn.setValue( nIdx ,"TRPR_NM",       voReturnVal["TRPR_NM"]);          // 대상자명
			                dsActn.setValue( nIdx ,"SXDC_SE_CD",    voReturnVal["SXDC_SE_CD"]);       // 성별
			                dsActn.setValue( nIdx ,"BRTH_YMD",      voReturnVal["TRPR_BRTH_YMD"]);    // 생년월일
			                dsActn.setValue( nIdx ,"ACBG_SE_CD",    voReturnVal["ACBG_SE_CD"]);       // 학력구분코드
			                
			                util.Control.redraw(app, "grdActn");
			            }
			        });    
			    }
			}


