			function getMkcttPlaceSeCdChk(newVal){
			    
			    /* 2022-12-07 YOO.CHI.HOON 온라인으의 경우 작성제외조치 (활동대상지역) 여가부요청*/
			    var grdGroup = app.lookup("grpACTVT_TRGT_RGN_SGG_NM");
			    var formLot  = grdGroup.getLayout();
			    
			    if(newVal == "1"){
			        
			        grdGroup.enabled = true;

			        app.lookup("opt_ACTVT_TRGT_RGN_SGG_CD").style.removeClass("label");
			        app.lookup("opt_ACTVT_TRGT_RGN_SGG_CD").style.addClass("label require");
			        app.lookup("sipb3").userAttr("required", "Y");
			        
			    }else{
			        
			        grdGroup.enabled = false;
			        
			        app.lookup("opt_ACTVT_TRGT_RGN_SGG_CD").style.removeClass("label require");
			        app.lookup("opt_ACTVT_TRGT_RGN_SGG_CD").style.addClass("label");
			        app.lookup("sipb3").userAttr("required", "N");        
			    }
			        
			        if(msCrudType == 'CREATE' || msCrudType == 'UPDATE'){
			            util.DataMap.setValue(app, "dmDetail", "ACTVT_TRGT_RGN_SGG_CD", null);
			            util.DataMap.setValue(app, "dmDetail", "ACTVT_TRGT_RGN_SGG_NM", null);
			            util.DataMap.setValue(app, "dmDetail", "ACTVT_TRGT_RGN_DTL_PLACE_NM", null);    
			            
			            var grdList = app.lookup("grdActn");
			            var grdCnt  = grdList.getRowCount();
			            
			            if (grdCnt <= 0) return false;
			            for(var idx = 0; idx < grdCnt; idx++){
			                
			                grdList.getRow(idx).setValue("MKCTT_PLACE_SE_CD" , null);
			                grdList.getRow(idx).setValue("MKCTT_PLACE_ETC_NM", null);
			            }
			        }
			    grdGroup.redraw();    
			    
			}

